import{_ as r,o as t,c as s,a4 as a}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"Ce qui manque encore","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"Ce qui manque encore","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/referent/ce-qui-manque-encore.md","filePath":"documentation/referent/ce-qui-manque-encore.md"}'),n={name:"documentation/referent/ce-qui-manque-encore.md"};function o(i,e,u,c,d,l){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="ce-qui-manque-encore" tabindex="-1">Ce qui manque encore <a class="header-anchor" href="#ce-qui-manque-encore" aria-label="Permalink to &quot;Ce qui manque encore {#ce-qui-manque-encore}&quot;">​</a></h1><p>Cette pile démarre, sert du HTTPS, se sauvegarde chaque nuit (et copie ses sauvegardes chiffrées chez un hébergeur), se met à jour avec retour arrière automatique et redémarre seule après un redémarrage du serveur. Elle ne fait pas encore :</p><ul><li><strong>déduplier réellement les copies distantes</strong> : les sauvegardes locales sont des archives compressées, le dépôt distant pèse à peu près la somme des copies conservées (<a href="/teuthis-cms-distribution/developpeurs/adr/0070-copie-distante-chiffree-des-sauvegardes-par-restic">ADR-0070</a>) ;</li><li><strong>vous prévenir par courriel</strong> d&#39;une copie distante en échec : elle se voit à <code>teuthis etat</code>, au conteneur <code>unhealthy</code> et au diagnostic, mais n&#39;envoie rien ;</li><li><strong>passer seule par les versions intermédiaires</strong> quand on saute plusieurs versions mineures : <code>teuthis mettre-a-jour</code> avertit alors, et la mise à jour n&#39;est garantie que depuis la version mineure précédente — lisez les notes de chaque version sautée ;</li><li>les autres sous-commandes prévues par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0045-deploiement-par-un-exploitant-non-developpeur">ADR-0045</a> (<code>configurer</code>, <code>cle-installation</code>, <code>journaux</code>, <code>desinstaller</code>) ;</li><li><strong>être éprouvée contre un vrai fournisseur</strong> : la CI n&#39;a exercé la copie distante que contre un MinIO et un serveur SFTP locaux (recette à faire sur un serveur jetable).</li></ul>',3)])])}const q=r(n,[["render",o]]);export{m as __pageData,q as default};
